insert into public.courses(slug,title,description,difficulty,is_published) values('ut-foundations','Ultrasonic Testing Learning Academy','A seven-module theory pathway from UT fundamentals through advanced methods and practical reporting.','Beginner',true) on conflict(slug) do update set title=excluded.title,description=excluded.description,is_published=true,updated_at=now();
insert into public.modules(course_id,position,title,description,is_published) select id,1,'UT Fundamentals','Sound-wave physics, frequency, wavelength, velocity and attenuation.',true from public.courses where slug='ut-foundations' on conflict(course_id,position) do update set title=excluded.title,description=excluded.description,is_published=true,updated_at=now();
insert into public.lessons(module_id,position,slug,title,difficulty,content,is_published) select m.id,1,'ut-fundamentals','Wave velocity, frequency and wavelength','Beginner','{"introduction":"UT uses high-frequency mechanical waves to examine a component without intentionally damaging it.","learning_objectives":["Define frequency, wavelength and velocity.","Use v = fλ with consistent units.","Explain why material and wave mode matter."],"explanation":["Frequency is cycles per second; wavelength is the distance between equivalent points on successive cycles.","At fixed velocity, increasing frequency decreases wavelength and can increase attenuation."],"equations":["v = f × λ","λ = v / f"],"worked_example":"At 5,920 m/s and 5 MHz, wavelength = 1.184 mm.","common_mistakes":["Mixing MHz and Hz.","Using longitudinal velocity for a shear wave."],"summary":"Identify material, wave mode and units before calculating."}'::jsonb,true from public.modules m join public.courses c on c.id=m.course_id where c.slug='ut-foundations' and m.position=1 on conflict(slug) do update set title=excluded.title,difficulty=excluded.difficulty,content=excluded.content,is_published=true,updated_at=now();
insert into public.modules(course_id,position,title,description,is_published) select id,2,'Equipment and Probes','Instrument controls, probe construction, couplant and probe selection.',true from public.courses where slug='ut-foundations' on conflict(course_id,position) do update set title=excluded.title,description=excluded.description,is_published=true,updated_at=now();
insert into public.lessons(module_id,position,slug,title,difficulty,content,is_published) select m.id,1,'equipment-and-probes','Probe selection and coupling fundamentals','Beginner','{"introduction":"A UT system includes the instrument, transducer, cable, coupling path and reference standard.","learning_objectives":["Describe probe and couplant roles.","Compare contact, angle-beam and immersion probes."],"explanation":["Probe frequency, aperture, damping and beam profile influence performance. Couplant reduces the air gap between probe and component."],"equations":["λ = v / f","Z = ρv"],"worked_example":"A lower frequency may be appropriate for a highly attenuating material, subject to procedure requirements.","common_mistakes":["Scanning with a damaged cable or unstable coupling."],"summary":"Probe choice and coupling are part of the inspection technique."}'::jsonb,true from public.modules m join public.courses c on c.id=m.course_id where c.slug='ut-foundations' and m.position=2 on conflict(slug) do update set title=excluded.title,difficulty=excluded.difficulty,content=excluded.content,is_published=true,updated_at=now();
insert into public.modules(course_id,position,title,description,is_published) select id,3,'Calibration','Zero, range, sensitivity, reference blocks, DAC/TCG and verification.',true from public.courses where slug='ut-foundations' on conflict(course_id,position) do update set title=excluded.title,description=excluded.description,is_published=true,updated_at=now();
insert into public.lessons(module_id,position,slug,title,difficulty,content,is_published) select m.id,1,'calibration','Calibration and verification fundamentals','Beginner','{"introduction":"Calibration relates instrument response to known distances or reference reflectors.","learning_objectives":["Distinguish range and sensitivity.","Explain verification and traceability."],"explanation":["Range maps time to sound path. Sensitivity establishes a response from a defined reflector. DAC and TCG compensate for path-related response changes as specified by procedure."],"equations":["d = v × t / 2","ΔdB = 20 log₁₀(A₂/A₁)"],"worked_example":"Doubling comparable amplitude requires about 6.02 dB increase.","common_mistakes":["Using incorrect velocity or skipping verification."],"summary":"Calibration is specific to the setup and governing procedure."}'::jsonb,true from public.modules m join public.courses c on c.id=m.course_id where c.slug='ut-foundations' and m.position=3 on conflict(slug) do update set title=excluded.title,difficulty=excluded.difficulty,content=excluded.content,is_published=true,updated_at=now();
insert into public.modules(course_id,position,title,description,is_published) select id,4,'Signal Interpretation','A-scan, back-wall echoes, noise, amplitude and TOF.',true from public.courses where slug='ut-foundations' on conflict(course_id,position) do update set title=excluded.title,description=excluded.description,is_published=true,updated_at=now();
insert into public.lessons(module_id,position,slug,title,difficulty,content,is_published) select m.id,1,'signal-interpretation','Reading an A-scan response','Beginner','{"introduction":"An A-scan plots signal amplitude against time or calibrated sound path.","learning_objectives":["Identify A-scan axes.","Explain why an echo needs context."],"explanation":["Echoes may arise from discontinuities, geometry or coupling changes. Interpretation combines position, sound path, calibration, repeatability and acceptance criteria."],"equations":["SNR(dB) = 20 log₁₀(A_signal/A_noise)"],"worked_example":"A signal amplitude four times representative noise gives about 12 dB amplitude SNR.","common_mistakes":["Calling every intermediate echo a defect."],"summary":"No single signal feature automatically identifies a defect."}'::jsonb,true from public.modules m join public.courses c on c.id=m.course_id where c.slug='ut-foundations' and m.position=4 on conflict(slug) do update set title=excluded.title,difficulty=excluded.difficulty,content=excluded.content,is_published=true,updated_at=now();
insert into public.modules(course_id,position,title,description,is_published) select id,5,'Inspection Techniques','Pulse-echo, through-transmission, thickness and scan coverage.',true from public.courses where slug='ut-foundations' on conflict(course_id,position) do update set title=excluded.title,description=excluded.description,is_published=true,updated_at=now();
insert into public.lessons(module_id,position,slug,title,difficulty,content,is_published) select m.id,1,'inspection-techniques','Pulse-echo and through-transmission','Intermediate','{"introduction":"Technique determines how sound enters the part, travels and is detected.","learning_objectives":["Compare pulse-echo and through-transmission.","Explain the round-trip factor."],"explanation":["Pulse-echo uses returned signals; through-transmission detects energy at a separate receiver. A scan plan defines path, overlap, orientation and recording."],"equations":["Pulse-echo thickness: d = v × t / 2"],"worked_example":"At 5,920 m/s and 8 μs round-trip time, estimated thickness is 23.68 mm.","common_mistakes":["Confusing one-way and round-trip time."],"summary":"Calibration, scan coverage and documentation work together."}'::jsonb,true from public.modules m join public.courses c on c.id=m.course_id where c.slug='ut-foundations' and m.position=5 on conflict(slug) do update set title=excluded.title,difficulty=excluded.difficulty,content=excluded.content,is_published=true,updated_at=now();
insert into public.modules(course_id,position,title,description,is_published) select id,6,'Advanced UT','PAUT, TOFD, immersion, automated scanning and C-scan.',true from public.courses where slug='ut-foundations' on conflict(course_id,position) do update set title=excluded.title,description=excluded.description,is_published=true,updated_at=now();
insert into public.lessons(module_id,position,slug,title,difficulty,content,is_published) select m.id,1,'advanced-ut','Introduction to PAUT, TOFD and C-scan','Intermediate','{"introduction":"Advanced UT combines array beam control, diffraction, controlled water paths and mapped data.","learning_objectives":["Describe PAUT and TOFD.","Explain C-scan and water-path stability."],"explanation":["PAUT uses timing delays across array elements. TOFD uses diffracted signals from tips. C-scan maps selected signal data to scan coordinates."],"equations":["Water-path TOF = water path / water velocity"],"worked_example":"A changing water path changes measured time even when the component is unchanged.","common_mistakes":["Ignoring water-path variation or encoder errors."],"summary":"Advanced techniques need validated scan plans and method-specific calibration."}'::jsonb,true from public.modules m join public.courses c on c.id=m.course_id where c.slug='ut-foundations' and m.position=6 on conflict(slug) do update set title=excluded.title,difficulty=excluded.difficulty,content=excluded.content,is_published=true,updated_at=now();
insert into public.modules(course_id,position,title,description,is_published) select id,7,'Practical Applications','Procedure-based examples, reporting and troubleshooting.',true from public.courses where slug='ut-foundations' on conflict(course_id,position) do update set title=excluded.title,description=excluded.description,is_published=true,updated_at=now();
insert into public.lessons(module_id,position,slug,title,difficulty,content,is_published) select m.id,1,'practical-applications','Inspection records and troubleshooting','Intermediate','{"introduction":"A practical inspection must produce repeatable evidence and a traceable record.","learning_objectives":["List key report fields.","Describe safe troubleshooting."],"explanation":["Records commonly identify component, procedure, equipment, probe, calibration, coverage, data, findings and limitations."],"equations":["Acceptance criteria come from the approved procedure and governing requirements."],"worked_example":"For a changing response, check coupling, setup, calibration and scan position, then follow the procedure.","common_mistakes":["Changing setup without recording it."],"summary":"Never invent acceptance criteria or tune away an indication."}'::jsonb,true from public.modules m join public.courses c on c.id=m.course_id where c.slug='ut-foundations' and m.position=7 on conflict(slug) do update set title=excluded.title,difficulty=excluded.difficulty,content=excluded.content,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('A-scan','A display of ultrasonic signal amplitude versus time or calibrated sound path.','UT',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('Acoustic impedance','Product of medium density and sound velocity for a specified wave mode.','UT',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('Attenuation','Reduction in sound amplitude due to absorption, scattering and other losses.','UT',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('Back-wall echo','An echo returned from the far boundary of the inspected component.','UT',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('Couplant','A medium used to improve sound transmission between probe and component.','UT',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('DAC','Distance-amplitude correction curve used to compare reference responses over sound path.','UT',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('PAUT','Phased array ultrasonic testing using electronically controlled delays across array elements.','PAUT',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('TCG','Time-corrected gain applying time-dependent gain to compensate for path-related response changes.','UT',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('TOFD','Time-of-flight diffraction technique using diffracted signals from discontinuity tips.','TOFD',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
insert into public.glossary_terms(term,definition,method,is_published) values('C-scan','A plan-view map of selected ultrasonic data over a scanned area.','Automated UT',true) on conflict(term) do update set definition=excluded.definition,method=excluded.method,is_published=true,updated_at=now();
